export function instructionTicket(id){
 const shapes={fold:'<path d="M20 22h62v52H20Z" fill="#fffef9"/><path d="m20 22 31 26 31-26M51 48v26" fill="none"/>',insert:'<path d="M15 48h70v37H15Z" fill="#e9b84a"/><path d="m15 48 35 23 35-23" fill="none"/><path d="M34 11h34v41H34Z" fill="#fffef9"/><path d="m44 24 7 8 8-8m-8 8V17" fill="none"/>',seal:'<path d="M15 24h70v54H15Z" fill="#e9b84a"/><path d="m15 24 35 30 35-30" fill="none"/><circle cx="50" cy="54" r="9" fill="#85627d"/>',arrow:'<path d="M50 43v47"/><path d="M12 23h47V12l29 24-29 24V49H12Z" fill="#e9b84a"/>',card:'<path d="M8 65h84M19 65v25m62-25v25" stroke-width="5"/><path d="m29 62 12-34h29l11 34Z" fill="#fffef9"/><path d="M42 45h23" stroke-width="4"/>',invite:'<path d="M13 22h74v44H56L43 82V66H13Z" fill="#abc4da"/><path d="M28 40h44M28 51h28"/>'};
 return `<svg viewBox="0 0 100 100" aria-hidden="true"><g stroke="#183f39" stroke-width="2.5" stroke-linejoin="round">${shapes[id]||''}</g></svg>`;
}
export function instructionScene(caseId,scene={}){
 if(caseId==='pocket-note'){
  const folded=scene.note==='folded-table',inside=scene.note==='inside',sealed=scene.envelope==='sealed';
  return svg(`<rect x="0" y="0" width="420" height="230" fill="#abc4da" stroke="none"/><path d="M18 159h384v19H18Z" fill="#c3a77b"/><path d="M44 178v44m332-44v44" stroke-width="8"/>${!inside?`<path d="M${folded?105:37} 100h${folded?69:138}v52H${folded?105:37}Z" fill="#fffef9"/><path d="M${folded?116:55} 116h${folded?42:102}m-${folded?42:102} 13h${folded?35:90}" fill="none"/>`:''}<path d="M242 111h92v44h-92Z" fill="#e9b84a"/>${sealed?'<path d="m242 111 46 31 46-31" fill="none"/><circle cx="288" cy="140" r="8" fill="#85627d"/>':'<path d="m242 111 46-35 46 35" fill="#fff3cf"/><path d="m242 155 35-26m57 26-35-26" fill="none"/>'}${inside&&!sealed?'<path d="M258 91h61v37h-61Z" fill="#fffef9"/><path d="m259 94 29 17 30-17" fill="none"/>':''}<g fill="#183f39" stroke="none" font-family="Trebuchet MS,sans-serif" font-size="14"><text x="${folded?104:37}" y="199">${inside?'Note is inside':folded?'Folded once':'Unfolded note'}</text><text x="242" y="199">${sealed?'Sealed envelope':'Open envelope'}</text></g>`);
 }
 const arrow=scene.arrowReady===true||scene.arrow===true,card=scene.cardReady===true||scene.card===true;
 const rabbit=scene.rabbit||scene.rabbitLocation||'not-invited';
 const atTable=['table','recognized','welcome-table','unrecognized-table'].includes(rabbit),atFork=['fork','stopped-at-fork'].includes(rabbit);
 return `<div class="instruction-map">${svg(`<rect width="420" height="230" fill="#abc4da" stroke="none"/><path d="M0 121q100-35 210-6t210-2v117H0Z" fill="#b8d4c3" stroke="none"/><path d="M136 230 185 158 144 102m41 56 117-48" fill="none" stroke="#e2cf9f" stroke-width="25"/><path d="M221 123q-29-50 15-61 39-11 55 31l-7 53Z" fill="#397958"/><path d="M304 124h94v12h-94Z" fill="#c3a77b"/><path d="M316 136v37m70-37v37" stroke-width="6"/>${card?'<path d="m334 123 7-28h29l10 28Z" fill="#fffef9"/><path d="M345 109h22"/>':'<path d="m377 179 7-22h25v22Z" fill="#fffef9"/>'}${arrow?'<path d="M170 154v-50"/><path d="M145 96h34V85l27 19-27 19v-11h-34Z" fill="#e9b84a"/>':'<path d="M72 163v44m-22-44h32v-10l25 18-25 18v-10H50Z" fill="#e9b84a"/>'}<g fill="#183f39" stroke="none" font-family="Trebuchet MS,sans-serif" font-size="13"><text x="113" y="83">Fork</text><text x="305" y="75">Table beyond hedge</text><text x="8" y="29">Rabbit cannot see the table from the fork.</text></g>`)}${atTable||atFork?`<span class="instruction-map-rabbit ${atTable?'at-table':'at-fork'}">${puppetArt('rabbit')}</span>`:''}</div>`;
}
export function instructionToyExample(step=0){const inside=step===1||step===2,closed=step>=2,toy=inside?294:106;return svg(`<rect width="420" height="230" fill="#abc4da" stroke="none"/><path d="M22 192h377"/><path d="M222 111h143v79H222Z" fill="#c3a77b"/><circle cx="${toy}" cy="${inside?137:162}" r="28" fill="#85627d"/><path d="m${toy-14} ${inside?127:152} 28 18m-27-2 25-15" stroke="#fffef9"/>${closed?'<path d="M217 102h153v14H217Z" fill="#e9b84a"/>':'<path d="m222 111 36-35h143l-36 35Z" fill="#e9b84a"/>'}<text x="22" y="37" fill="#183f39" stroke="none" font-family="Trebuchet MS,sans-serif" font-size="16">${['Before: toy outside, box open','Toy inside; box open','Toy inside; box closed','Close first: toy outside','Box stays closed; toy stays outside'][step]}</text>${inside&&closed?'<path d="M223 153h141" stroke-dasharray="5 5"/>':''}`);}
